{"code":"KP-0255","name":"Potreba po nalaganju Oven Managerja","instruction":"Preveri, če je potrebno naložiti Oven Manager\nCheck if Oven Manager needs to be loaded","input_type":"DA_NE","default_unit":null,"grp":"FUNKCIJA","phase":"ZAKLJUCEK_800","status":"AKTIVEN","default_order":808,"sequence_number":281,"internal_note":"Obrazec Končni preizkus, točka 281.","affiliations":["OCB","ODC","PV-B"]},
{"code":"KP-0256","name":"Praznjenje agregata","instruction":"Praznjenje agregata, s črpalko se izprazni voda\nEmptey the steam generator, water is emptied with water pump","input_type":"DA_NE","default_unit":null,"grp":"ROCNO_DELO","phase":"ZAKLJUCEK_800","status":"AKTIVEN","default_order":809,"sequence_number":282,"internal_note":"Obrazec Končni preizkus, točka 282.","affiliations":["OCB"]},
{"code":"KP-0257","name":"Končni vizualni pregled pred embaliranjem","instruction":"Končni vizualni pregled proizvoda pred embaliranjem (prisotne nesmejo biti praske, udrtine itd.)\nFinal visual inspection of the product before packaging (scratches, dents, etc.,)","input_type":"OK_NOK","default_unit":null,"grp":"VIZUALNO","phase":"ZAKLJUCEK_800","status":"AKTIVEN","default_order":810,"sequence_number":283,"internal_note":"Obrazec Končni preizkus, točka 283.","affiliations":["OCA","OCB","ODC","OPD","PV-B","SCH"]},
{"code":"KP-0258","name":"Ožičenje elektro plošče","instruction":"Na elektro plošči preveri ožičenje.\nCheck the wiring on the electrical panel.","input_type":"OK_NOK","default_unit":null,"grp":"ELEKTRIKA","phase":"PRIPRAVA_0","status":"AKTIVEN","default_order":19,"sequence_number":284,"internal_note":"Obrazec Končni preizkus, točka 284.","affiliations":[]},
{"code":"KP-0259","name":"Priklop brike za TF1 in TF2","instruction":"Na elektro ploščo priklopi briko za TF1 in TF2.\nConnect the bridge for TF1 and TF2 to the electrical panel.","input_type":"DA_NE","default_unit":null,"grp":"ELEKTRIKA","phase":"PRIPRAVA_0","status":"AKTIVEN","default_order":20,"sequence_number":285,"internal_note":"Obrazec Končni preizkus, točka 285.","affiliations":[]},
{"code":"KP-0260","name":"Priklop LED indikacije EMV, nape in motorja","instruction":"Na elektro ploščo priklopi led indikacijo za EMV, 1 in 2 hitrost nape, belimo motor.\nConnect the LED indication for EMV, 1st and 2nd speed of the hood, bleach motor to the electrical panel.","input_type":"DA_NE","default_unit":null,"grp":"ELEKTRIKA","phase":"PRIPRAVA_0","status":"AKTIVEN","default_order":21,"sequence_number":286,"internal_note":"Obrazec Končni preizkus, točka 286.","affiliations":[]},
{"code":"KP-0261","name":"Priklop enofaznega napajalnega kabla","instruction":"Na elektro ploščo priklopi enofazni napajalni kabel.\nConnect the single-phase power cable to the electrical panel.","input_type":"DA_NE","default_unit":null,"grp":"ELEKTRIKA","phase":"PRIPRAVA_0","status":"AKTIVEN","default_order":22,"sequence_number":287,"internal_note":"Obrazec Končni preizkus, točka 287.","affiliations":[]},
{"code":"KP-0262","name":"Odklop žice na kontaktorju K1 (T1)","instruction":"Na elektro plošči odklopi žico na kontaktorju K1 kontakt T1.\nDisconnect the wire at contactor K1 contact T1 on the electrical panel.","input_type":"DA_NE","default_unit":null,"grp":"ELEKTRIKA","phase":"PRIPRAVA_0","status":"AKTIVEN","default_order":23,"sequence_number":288,"internal_note":"Obrazec Končni preizkus, točka 288.","affiliations":[]},
{"code":"KP-0263","name":"Priklop main boarda in temperaturnih sond","instruction":"Na elektro ploščo priklopi main board in priklopi temperaturne sonde (2x 1,5m in 1x 2,0m) na main board.\nConnect the main board to the electrical panel and connect the temperature probes(2x 1,5m and 1x 2,0m) to the main board.","input_type":"DA_NE","default_unit":null,"grp":"ELEKTRIKA","phase":"PRIPRAVA_0","status":"AKTIVEN","default_order":24,"sequence_number":289,"internal_note":"Obrazec Končni preizkus, točka 289.","affiliations":[]},
{"code":"KP-0264","name":"USB s FW, Erase Flash in aktivacijska koda","instruction":"Vstavi USB z FW-jem v krmilnik in prikolpi na preizkusno mesto. Preveri za Erase Flash ob zagonu in nato vpiši aktivacisko kodo.\nInsert the USB with FW into the controller and connect it to the test location. Check for Erase Flash at startup and then enter the activation code.","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"PRED_ZAGONOM_100","status":"AKTIVEN","default_order":138,"sequence_number":290,"internal_note":"Obrazec Končni preizkus, točka 290.","affiliations":[]},
{"code":"KP-0265","name":"Vstop v servisni meni (koda 1234)","instruction":"Vklopi krmilnik in vstopi v servisni meni, s kodo 1234.\nEnter in service menu, with code 1234.","input_type":"DA_NE","default_unit":null,"grp":"FUNKCIJA","phase":"PRED_ZAGONOM_100","status":"AKTIVEN","default_order":139,"sequence_number":291,"internal_note":"Obrazec Končni preizkus, točka 291.","affiliations":[]},
{"code":"KP-0266","name":"Ura, datum in časovna kalibracija","instruction":"Nastavi uro, datum in časovno kalibracijo (64)\nSet the clock, date, and time calibration (64)","input_type":"DA_NE","default_unit":null,"grp":"FUNKCIJA","phase":"PRED_ZAGONOM_100","status":"AKTIVEN","default_order":140,"sequence_number":292,"internal_note":"Obrazec Končni preizkus, točka 292.","affiliations":[]},
{"code":"KP-0267","name":"Vstop v IO MENU","instruction":"Vstop v IO MENU (starejši COMM-SETUP).\nEnter in IO Menu (old COMM-SETUP).","input_type":"DA_NE","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":355,"sequence_number":293,"internal_note":"Obrazec Končni preizkus, točka 293.","affiliations":[]},
{"code":"KP-0268","name":"Prikaz temperature generatorja pare T-st","instruction":"Preveri prikaz temperature generatorja pare T-st (prikaz temp. je enak ambientalne temp.)\nCheck the steam generator temperature display T-st (displayed temp. is same as ambienal temp.)","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":356,"sequence_number":294,"internal_note":"Obrazec Končni preizkus, točka 294.","affiliations":[]},
{"code":"KP-0269","name":"Kontaktor K1 (OUT1) in LED prve hitrosti nape","instruction":"Vklop glavnega kontaktorja K1 (OUT1) vklopijo Led indikacija za prvo hitrosti nape.\nTurn on the main contactor K1 (OUT1) to activate the LED indication for the first hood speed.","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":357,"sequence_number":295,"internal_note":"Obrazec Končni preizkus, točka 295.","affiliations":[]},
{"code":"KP-0270","name":"Elektromagnetni ventil agregata (OUT2)","instruction":"Vkolp elektromagnetnega ventila za v agregat (OUT2) preveri delovanje (indikacijo led) nato izklopite elektromagnetni ventil (OUT2).\nActivate the water solenoid valve for the unit (OUT2), check operation (LED indication), then turn off the solenoid valve (OUT2).","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":358,"sequence_number":296,"internal_note":"Obrazec Končni preizkus, točka 296.","affiliations":[]},
{"code":"KP-0271","name":"Kontaktor zgornjega grelca (OUT3)","instruction":"Preizkus vkolopa in izklopa kontaktorja zgornjega grelca (OUT3)\nTest the operation of turning on and off the top heater contactor (OUT3)","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":359,"sequence_number":297,"internal_note":"Obrazec Končni preizkus, točka 297.","affiliations":[]},
{"code":"KP-0272","name":"Kontaktor spodnjega grelca (OUT19)","instruction":"Preizkus vkolopa in izklopa kontaktorja spodnjega grelca (OUT19)\nTest the operation of turning on and off the bottom heater contactor (OUT19)","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":360,"sequence_number":298,"internal_note":"Obrazec Končni preizkus, točka 298.","affiliations":[]},
{"code":"KP-0273","name":"Kontaktor grelcev agregata (OUT7)","instruction":"Preizkus vkolopa in izklopa kontaktorja za grelce agregata (OUT7)\nTest the operation of turning on and off the contactor for the unit heaters (OUT7)","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":361,"sequence_number":299,"internal_note":"Obrazec Končni preizkus, točka 299.","affiliations":[]},
{"code":"KP-0274","name":"Odpiranje lopute dimnika (OUT6)","instruction":"Odpiranje lopute dimnika (OUT6) preveri delovanje (Led indikacijo) nato iklopi (OUT6).\nOpen the chimney flap (OUT6), check operation (LED indication), then turn off (OUT6).","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":362,"sequence_number":300,"internal_note":"Obrazec Končni preizkus, točka 300.","affiliations":[]},
{"code":"KP-0275","name":"Zapiranje lopute dimnika (OUT18)","instruction":"Zapiranje lopute dimnika (OUT18) preveri delovanje (Led indikacijo) nato iklopi (OUT18).\nClose the chimney flap (OUT18), check operation (LED indication), then turn off (OUT18).","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":363,"sequence_number":301,"internal_note":"Obrazec Končni preizkus, točka 301.","affiliations":[]},
{"code":"KP-0276","name":"Druga hitrost nape (OUT5)","instruction":"Delovanje druge hitrosti nape (OUT5) preveri delovanje (led indikacijo) nato izklopi (OUT5)\nTest the operation of the second speed of the hood (OUT5), check operation (LED indication), then turn off (OUT5)","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":364,"sequence_number":302,"internal_note":"Obrazec Končni preizkus, točka 302.","affiliations":[]},
{"code":"KP-0277","name":"LED osvetlitev (OUT4)","instruction":"Vklop LED osvetlitve z vkolpom izhoda OUT4 preveri delovanje nato izklopiti izhod OUT4.\nTurn on the LED lighting by activating output OUT4, check its operation, and then deactivate output OUT4.","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":365,"sequence_number":303,"internal_note":"Obrazec Končni preizkus, točka 303.","affiliations":[]},
{"code":"KP-0278","name":"Izhod iz IO MENU na MANUAL","instruction":"Izhod iz IO MENU (starejši COMM-SETUP), na nastavitev MANUAL\nExit from IO MENU, go to MANUAL menu","input_type":"DA_NE","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":366,"sequence_number":304,"internal_note":"Obrazec Končni preizkus, točka 304.","affiliations":[]},
{"code":"KP-0279","name":"Vstop v MANUAL način","instruction":"Vstopu v MANUAL mode\nEnter in MANUAL menu","input_type":"DA_NE","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":367,"sequence_number":305,"internal_note":"Obrazec Končni preizkus, točka 305.","affiliations":[]},
{"code":"KP-0280","name":"Prikaz temperature etaž","instruction":"Preveri prikaz temperature zgornje in spodnje etaže. Prikaz trenutne temperature je sobna temperatura.\nCheck the temperature display of the upper and lower floors. The current temperature display is room temperature.","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":368,"sequence_number":306,"internal_note":"Obrazec Končni preizkus, točka 306.","affiliations":[]},
{"code":"KP-0281","name":"Vklop kontaktorjev in izklop K2–K4","instruction":"Vklop vseh kontaktorjev. Zmašaj temperaturo zgornje in spodnje etaže na 10°C in izklopi agregat in preveri izklop K2, K3 in K4.\nContactors turn on. Set the temperature of the upper and lower floors to 10°C, turn off the generator, and check the shutdown of K2, K3, and K4.","input_type":"OK_NOK","default_unit":null,"grp":"FUNKCIJA","phase":"ROCNI_TEST_200","status":"AKTIVEN","default_order":369,"sequence_number":307,"internal_note":"Obrazec Končni preizkus, točka 307.","affiliations":[]},
{"code":"KP-0282","name":"Izklop krmilnika in preizkusnega mesta","instruction":"Izklopi krmilnik in nato izklopi iz preizkusnega mesta\nTurn off the controller and then disconnect from the testing place.","input_type":"DA_NE","default_unit":null,"grp":"ROCNO_DELO","phase":"ZAKLJUCEK_800","status":"AKTIVEN","default_order":811,"sequence_number":308,"internal_note":"Obrazec Končni preizkus, točka 308.","affiliations":[]},
{"code":"KP-0283","name":"Odklop testnih priključkov in priklop žice na kontaktor","instruction":"Na elektro pošči odklopimo vse led indikacije, napajalni kabel, brike in nazaj priklopimo žico na kontaktor\nOn the electrical panel, disconnect all LED indications, the power cable, bridges, and reconnect the wire to the contactor.","input_type":"DA_NE","default_unit":null,"grp":"ELEKTRIKA","phase":"ZAKLJUCEK_800","status":"AKTIVEN","default_order":812,"sequence_number":309,"internal_note":"Obrazec Končni preizkus, točka 309.","affiliations":[]},
{"code":"KP-0284","name":"Kontrola ožičenja","instruction":"Preveri ožičenje.\nCheck the wiring.","input_type":"OK_NOK","default_unit":null,"grp":"ELEKTRIKA","phase":"ZAKLJUCEK_800","status":"AKTIVEN","default_order":813,"sequence_number":310,"internal_note":"Obrazec Končni preizkus, točka 310.","affiliations":[]}]$json$::jsonb;
  v_count integer;
BEGIN
  IF to_regclass('public.ln_kp_postopki_pripadnost') IS NULL THEN
    RAISE EXCEPTION 'Najprej izvedite 003_sifranti.sql in 004_pripadnosti_meritve.sql.';
  END IF;
  SELECT count(*) INTO v_count FROM jsonb_to_recordset(v_rows) AS u(code text, name text, instruction text, input_type text, default_unit text, grp text, phase text, status text, default_order integer, sequence_number integer, internal_note text, affiliations jsonb)
    WHERE NOT EXISTS (SELECT 1 FROM public.kp_tipi_vnosa WHERE code = u.input_type)
       OR NOT EXISTS (SELECT 1 FROM public.kp_skupine WHERE code = u.grp)
       OR NOT EXISTS (SELECT 1 FROM public.kp_faze_testa WHERE code = u.phase)
       OR NOT EXISTS (SELECT 1 FROM public.kp_statusi_postopkov WHERE code = u.status)
       OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(u.affiliations) c WHERE NOT EXISTS (SELECT 1 FROM public.kp_pripadnosti WHERE code = c));
  IF v_count > 0 THEN RAISE EXCEPTION 'Uvoz uporablja vrednost, ki je ni v šifrantih (% postopkov).', v_count; END IF;

  UPDATE public.kp_postopki p SET
    name = u.name, instruction = u.instruction, default_unit = u.default_unit, default_order = u.default_order, sequence_number = u.sequence_number,
    internal_note = u.internal_note, active = true, visible = true,
    input_type_id = (SELECT id FROM public.kp_tipi_vnosa WHERE code = u.input_type),
    group_id = (SELECT id FROM public.kp_skupine WHERE code = u.grp),
    test_phase_id = (SELECT id FROM public.kp_faze_testa WHERE code = u.phase),
    status_id = (SELECT id FROM public.kp_statusi_postopkov WHERE code = u.status)
  FROM jsonb_to_recordset(v_rows) AS u(code text, name text, instruction text, input_type text, default_unit text, grp text, phase text, status text, default_order integer, sequence_number integer, internal_note text, affiliations jsonb) WHERE p.code = u.code;

  INSERT INTO public.kp_postopki(code, name, instruction, default_unit, default_order, sequence_number, internal_note, input_type_id, group_id, test_phase_id, status_id)
  SELECT u.code, u.name, u.instruction, u.default_unit, u.default_order, u.sequence_number, u.internal_note,
    (SELECT id FROM public.kp_tipi_vnosa WHERE code = u.input_type), (SELECT id FROM public.kp_skupine WHERE code = u.grp),
    (SELECT id FROM public.kp_faze_testa WHERE code = u.phase), (SELECT id FROM public.kp_statusi_postopkov WHERE code = u.status)
  FROM jsonb_to_recordset(v_rows) AS u(code text, name text, instruction text, input_type text, default_unit text, grp text, phase text, status text, default_order integer, sequence_number integer, internal_note text, affiliations jsonb) WHERE NOT EXISTS (SELECT 1 FROM public.kp_postopki p WHERE p.code = u.code);

  -- Affiliations: hide the ones that are not in the form, add or restore the others.
  UPDATE public.ln_kp_postopki_pripadnost l SET visible = EXISTS (
    SELECT 1 FROM jsonb_to_recordset(v_rows) AS u(code text, name text, instruction text, input_type text, default_unit text, grp text, phase text, status text, default_order integer, sequence_number integer, internal_note text, affiliations jsonb) JOIN public.kp_pripadnosti a ON a.code IN (SELECT jsonb_array_elements_text(u.affiliations))
    WHERE u.code = p.code AND a.id = l.id_pripadnosti)
  FROM public.kp_postopki p WHERE p.id = l.id_postopka AND p.code IN (SELECT u.code FROM jsonb_to_recordset(v_rows) AS u(code text, name text, instruction text, input_type text, default_unit text, grp text, phase text, status text, default_order integer, sequence_number integer, internal_note text, affiliations jsonb));
  INSERT INTO public.ln_kp_postopki_pripadnost(id_postopka, id_pripadnosti)
  SELECT p.id, a.id FROM jsonb_to_recordset(v_rows) AS u(code text, name text, instruction text, input_type text, default_unit text, grp text, phase text, status text, default_order integer, sequence_number integer, internal_note text, affiliations jsonb) JOIN public.kp_postopki p ON p.code = u.code
    JOIN public.kp_pripadnosti a ON a.code IN (SELECT jsonb_array_elements_text(u.affiliations))
  ON CONFLICT (id_postopka, id_pripadnosti) DO UPDATE SET visible = true;

  RAISE NOTICE 'Uvoženih postopkov: %', jsonb_array_length(v_rows);
END;
$uvoz$;
